  9	/**
 10	 * Places each session inside the account's own waking day.
 11	 *
 12	 * The host flags a player whose fleet departures span eighteen or more distinct
 13	 * hours of the day (`ServerAdministrationController`, round-the-clock signal),
 14	 * so the routine needs a dark period the account never acts in. Every account
 15	 * keeps a nine-hour core dark period, long enough to block eight whole hours of
 16	 * every day whatever its clock offset, and each day's drift can only extend it:
 17	 * bed and wake times move the way a person's do, and the guarantee never
 18	 * shrinks (H1, H5).
 19	 */
 20	class SessionPlanner
 21	{
 22	    private const DAY_MINUTES = 1440;
 23	
 24	    /** The dark period every account keeps, whatever its wake time. */
 25	    private const CORE_DARK_MINUTES = 540;
 26	
 27	    /** Early bird to night owl: the span the account's wake time is drawn from. */
 28	    private const EARLIEST_WAKE_MINUTE = 330;
 29	
 30	    private const WAKE_SPREAD_MINUTES = 240;
 31	
 32	    /** How far one day's bed and wake time may slip past the account's core. */
 33	    private const DRIFT_MINUTES = 30;
 34	
 35	    /** Weibull shape below one: most waits are short and a few are long. */
 36	    private const TAIL_SHAPE = 0.8;
 37	
 38	    /** The mean of that shape, so a wait's own average is the wait it was given. */
 39	    private const TAIL_MEAN = 1.133;
 40	
 41	    /** Keeps the drawn unit away from zero, where its logarithm diverges. */
 42	    private const MINIMUM_UNIT = 1.0E-9;
 43	
 44	    /*
 45	     * Absences (H3). The plan states the bands per month, per quarter and per
 46	     * year, so they arrive here as per-day rates: one to three single days a
 47	     * month is about two days in thirty, one three-to-seven-day gap a quarter is
 48	     * one night in ninety, and one gap of a week or more a year is one in three
 49	     * hundred and sixty-five. Nothing reaches four weeks, which is where
 50	     * neighbours write an account off.
 51	     */
 52	    private const YEARLY_ABSENCE_RATE = 0.0027;
 53	
 54	    private const QUARTERLY_ABSENCE_RATE = 0.0137;
 55	
 56	    private const MONTHLY_ABSENCE_RATE = 0.0807;
 57	
 58	    /** Days added to the three-day gap and to the week-long one. */
 59	    private const MID_ABSENCE_SPREAD_DAYS = 3;
 60	
 61	    private const LONG_ABSENCE_SPREAD_DAYS = 3;
 62	
 63	    public function __construct(private RandomSource $randomSource)
 64	    {
 65	    }
