 67	    public function plan(AiProfile $profile, CarbonImmutable $now, int $generation): SessionPlan
 68	    {
 69	        $routine = RoutineProfile::fromAiProfile($profile);
 70	        $local = $now->setTimezone($routine->timezone);
 71	        [$wake, $bed] = $this->wakingWindow($profile, $local);
 72	        $wakingMinutes = (int) $wake->diffInMinutes($bed);
 73	        $step = max($routine->sessionMinutes + 1, intdiv($wakingMinutes, $routine->sessionsPerDay));
 74	        $waitBase = max(1, $step - $routine->sessionMinutes);
 75	
 76	        // A wait skips the dark period rather than the day: one unlucky draw
 77	        // must not park the account for a week and read as abandoned.
 78	        $sessionEndsAt = $this->earliest(
 79	            $local->addMinutes($this->wait($profile, $routine->sessionMinutes, 'length:' . $generation)),
 80	            $bed,
 81	        );
 82	        $wait = min($this->wait($profile, $waitBase, 'wait:' . $generation), $wakingMinutes);
 83	        $candidate = $sessionEndsAt->addMinutes($wait);
 84	        [$wake, $bed] = $this->wakingWindow($profile, $candidate);
 85	        $nextDueAt = $candidate;
 86	
 87	        // The account looks in again when it wakes up, so the wait that ran into
 88	        // the dark period is spent: reusing it would skip the day it just woke
 89	        // into, and an absence nobody planned reads as an abandoned account.
 90	        if ($candidate->lessThan($wake)) {
 91	            [$wake, $bed] = $this->wakingAfterAbsence($profile, $wake);
 92	            $nextDueAt = $this->firstSessionOf($wake, $bed, min($this->wait($profile, $waitBase, 'wake:' . $generation), $step));
 93	        }
 94	
 95	        return app()->makeWith(SessionPlan::class, [
 96	            'sessionEndsAt' => $sessionEndsAt,
 97	            'nextDueAt' => $nextDueAt,
 98	        ]);
 99	    }
100	
101	    /**
102	     * Whether the instant falls inside the account's waking window, i.e. the account
103	     * would be awake then rather than in its dark period (SP3). The day's own drift
104	     * is applied, so the answer is for the window the instant actually lands in.
105	     */
106	    public function isAwake(AiProfile $profile, CarbonImmutable $instant): bool
107	    {
108	        $local = $instant->setTimezone(RoutineProfile::fromAiProfile($profile)->timezone);
109	        [$wake, $bed] = $this->dayWindow($profile, $local->startOfDay());
110	
111	        return $local->greaterThanOrEqualTo($wake) && $local->lessThan($bed);
112	    }
113	
114	    /**
115	     * The waking window that contains the moment, or the next one when the
116	     * moment falls inside a dark period.
117	     *
118	     * @return array{0: CarbonImmutable, 1: CarbonImmutable}
119	     */
120	    private function wakingWindow(AiProfile $profile, CarbonImmutable $local): array
121	    {
122	        $day = $local->startOfDay();
123	        [$wake, $bed] = $this->dayWindow($profile, $day);
124	
125	        // Before today's wake the account is still in the dark period the
126	        // previous day ended with, and once it reaches today's bed the window
127	        // containing it is the next day's.
128	        if ($local->lessThan($wake)) {
129	            $day = $day->subDay();
130	            [$wake, $bed] = $this->dayWindow($profile, $day);
131	        }
132	
133	        if ($local->greaterThanOrEqualTo($bed)) {
134	            $day = $day->addDay();
135	            [$wake, $bed] = $this->dayWindow($profile, $day);
136	        }
137	
138	        return [$wake, $bed];
139	    }
140	
141	    /** @return array{0: CarbonImmutable, 1: CarbonImmutable} */
142	    private function dayWindow(AiProfile $profile, CarbonImmutable $day): array
143	    {
144	        $wakeMinute = $this->coreWakeMinute($profile) + $this->drift($profile, $day, 'wake');
145	        $bedMinute = $wakeMinute + self::DAY_MINUTES - self::CORE_DARK_MINUTES - $this->drift($profile, $day, 'bed');
146	
147	        return [$day->addMinutes($wakeMinute), $day->addMinutes($bedMinute)];
148	    }
149	
150	    /** The first session of a waking day: after waking, but never past its bed. */
151	    private function firstSessionOf(CarbonImmutable $wake, CarbonImmutable $bed, int $wait): CarbonImmutable
152	    {
153	        $start = $wake->addMinutes($wait);
154	
155	        return $start->lessThan($bed) ? $start : $bed->subMinute();
156	    }
