158	    /**
159	     * The day the account comes back to, which is not always the next one.
160	     *
161	     * @return array{0: CarbonImmutable, 1: CarbonImmutable}
162	     */
163	    private function wakingAfterAbsence(AiProfile $profile, CarbonImmutable $wake): array
164	    {
165	        return $this->wakingWindow($profile, $wake->addDays($this->absenceDays($profile, $wake)));
166	    }
167	
168	    /**
169	     * How many waking days the account is away for, decided once a night.
170	     *
171	     * A night away is a person's ordinary absence; a few days away is a trip;
172	     * a week or more is the holiday that also sets the host's inactive marker,
173	     * which humans do set.
174	     */
175	    private function absenceDays(AiProfile $profile, CarbonImmutable $day): int
176	    {
177	        $date = $day->toDateString();
178	        $unit = $this->randomSource->unitInterval($profile->random_seed, 'routine:absence:' . $date);
179	
180	        return match (true) {
181	            $unit < self::YEARLY_ABSENCE_RATE => 7 + $this->scaled($profile, 'routine:away-long:' . $date, self::LONG_ABSENCE_SPREAD_DAYS),
182	            $unit < self::QUARTERLY_ABSENCE_RATE => 3 + $this->scaled($profile, 'routine:away-mid:' . $date, self::MID_ABSENCE_SPREAD_DAYS),
183	            $unit < self::MONTHLY_ABSENCE_RATE => 1,
184	            default => 0,
185	        };
186	    }
187	
188	    private function coreWakeMinute(AiProfile $profile): int
189	    {
190	        return self::EARLIEST_WAKE_MINUTE + $this->scaled($profile, 'routine:anchor', self::WAKE_SPREAD_MINUTES);
191	    }
192	
193	    /** How far this day's bed or wake time slips past the account's core. */
194	    private function drift(AiProfile $profile, CarbonImmutable $day, string $edge): int
195	    {
196	        return $this->scaled($profile, 'routine:' . $edge . ':' . $day->toDateString(), self::DRIFT_MINUTES);
197	    }
