199	    /**
200	     * A Weibull draw, whose shape below one gives the heavy tail human activity
201	     * has: many short waits and the occasional long one. Jitter on a fixed
202	     * period would leave the period itself readable (H2, H5).
203	     */
204	    private function wait(AiProfile $profile, int $base, string $context): int
205	    {
206	        $unit = max($this->randomSource->unitInterval($profile->random_seed, $context), self::MINIMUM_UNIT);
207	        $drawn = ($base / self::TAIL_MEAN) * (-log($unit)) ** (1 / self::TAIL_SHAPE);
208	
209	        // Never zero: the account does not run two sessions in the same minute.
210	        return max(1, (int) round($drawn));
211	    }
212	
213	    private function scaled(AiProfile $profile, string $context, int $ceiling): int
214	    {
215	        return (int) round($this->randomSource->unitInterval($profile->random_seed, $context) * $ceiling);
216	    }
217	
218	    private function earliest(CarbonImmutable $first, CarbonImmutable $second): CarbonImmutable
219	    {
220	        return $first->lessThan($second) ? $first : $second;
221	    }
222	}

