  259	        // projection. The scorer never receives unseen defender information.
  260	        foreach ($perception->targetReports as $report) {
  261	            $reportKey = 'report:' . $report['report_id'];
  262	            if (!$report['attack_permitted']) {
  263	                $rejections[$reportKey] = AiCandidateRejectionReason::AttackNotPermitted->value;
  264	                continue;
  265	            }
  266	
  267	            if ($report['expires_at'] <= $perception->observedAt->getTimestamp()) {
  268	                $rejections[$reportKey] = AiCandidateRejectionReason::StaleTargetIntel->value;
  269	                continue;
  270	            }
  271	
  272	            // A target scoring under ~⅕ of ours cannot defend its loot, so it is
  273	            // dropped before the estimator runs (RAID-008). Fixtures built
  274	            // without the field stay viable rather than silently disappearing.
  275	            if (!($report['score_viable'] ?? true)) {
  276	                $rejections[$reportKey] = AiCandidateRejectionReason::ScoreBelowViability->value;
  277	                continue;
