    /**
     * Whether the host's own gate refuses this upgrade while units stand in this planet's
     * production queue -- the same predicate the executor's refusal names `shipyard_busy`.
     *
     * The planner has to ask it: a step offered past a gate the executor refuses spends the
     * planet's one queue slot and lands nothing, which leaves the planet buildable and idle. The
     * predicate is the host's, so the module names no object, and the host answers it for the
     * planet the player is looking at, which is the executor's own actor.
     */
    private function blockedByProduction(PlanetService $planet, int $buildingId): bool
    {
        return $planet->getPlayer()?->isObjectUpgradeBlocked($buildingId) === true;
    }

